import json
import os
import re
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

PROJECT_ROOT = Path('/home/rivotek/daichen/Work/Code/d13x_vela_0630').resolve()
SESSIONS_ROOT = Path('/home/rivotek/.codex/sessions')
LOG_ROOT = PROJECT_ROOT / 'logs'
GITHUB_LOGIN = 'daichen-AS'
TEAM_ID = 'contest2026_052_xinfanzhichuang'
TOOL = 'codex'
SCHEMA_VERSION = '1.0'
GENERATOR = 'codex-collector@1.2.0'
SINCE_DATE = '2026-07-06'

REDACT_RULES = [
    (re.compile(r'sk-[A-Za-z0-9_-]{20,}'), 'sk-***REDACTED***'),
    (re.compile(r'ghp_[A-Za-z0-9]{36}'), 'ghp_***REDACTED***'),
    (re.compile(r'Bearer\s+[A-Za-z0-9._\-+/=]+'), 'Bearer ***REDACTED***'),
]

SKIP_USER_PREFIXES = (
    '<environment_context>',
)


def iso_now() -> str:
    return datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.') + f'{datetime.now(timezone.utc).microsecond // 1000:03d}Z'


def redacted(value: Any, counter: list[int]) -> Any:
    if isinstance(value, str):
        out = value
        for pat, repl in REDACT_RULES:
            out, n = pat.subn(repl, out)
            counter[0] += n
        return out
    if isinstance(value, list):
        return [redacted(v, counter) for v in value]
    if isinstance(value, dict):
        return {k: redacted(v, counter) for k, v in value.items()}
    return value


def parse_json_arg(value: Any) -> Any:
    if not isinstance(value, str):
        return value
    try:
        return json.loads(value)
    except Exception:
        return value


def content_texts(content: Any) -> list[str]:
    if isinstance(content, str):
        return [content] if content else []
    if not isinstance(content, list):
        return []
    texts = []
    for block in content:
        if not isinstance(block, dict):
            continue
        bt = block.get('type')
        if bt in ('input_text', 'output_text', 'text'):
            text = block.get('text') or ''
            if text:
                texts.append(text)
    return texts


def is_project_cwd(cwd: str | None) -> bool:
    if not cwd:
        return False
    try:
        p = Path(cwd).expanduser().resolve()
        return p == PROJECT_ROOT or PROJECT_ROOT in p.parents
    except Exception:
        return False


def date_from_path(path: Path) -> str:
    # .../.codex/sessions/YYYY/MM/DD/rollout-...
    return '-'.join(path.parts[-4:-1])


def add_base(event: dict, session_id: str, seq: int, redacted_total: list[int]) -> dict:
    counter = [0]
    body = redacted(event, counter)
    redacted_total[0] += counter[0]
    out = {
        'schema_version': SCHEMA_VERSION,
        'session_id': session_id,
        'team_id': TEAM_ID,
        'github_login': GITHUB_LOGIN,
        'tool': TOOL,
        'seq': seq,
        **body,
    }
    if counter[0] > 0:
        out['redacted_count'] = counter[0]
    return out


def convert(path: Path) -> dict | None:
    session_date = date_from_path(path)
    if session_date < SINCE_DATE:
        return None

    raw_objects = []
    invalid_lines = 0
    with path.open(encoding='utf-8', errors='replace') as f:
        for line in f:
            if not line.strip():
                continue
            try:
                raw_objects.append(json.loads(line))
            except json.JSONDecodeError:
                invalid_lines += 1

    meta = next((o.get('payload') or {} for o in raw_objects if o.get('type') == 'session_meta'), {})
    cwd = meta.get('cwd')
    if not is_project_cwd(cwd):
        return None

    session_id = meta.get('session_id') or meta.get('id') or path.stem.split('-')[-1]
    started_at = meta.get('timestamp') or (raw_objects[0].get('timestamp') if raw_objects else iso_now())
    events = []
    redacted_total = [0]
    last_model = None
    last_tokens_total = None

    for obj in raw_objects:
        ts = obj.get('timestamp') or started_at
        top_type = obj.get('type')
        payload = obj.get('payload') or {}
        ptype = payload.get('type')

        if top_type == 'response_item':
            if ptype == 'message':
                role = payload.get('role')
                if role not in ('user', 'assistant', 'system'):
                    continue
                # The stored Codex transcript includes runtime context as a user-shaped message.
                # It is not part of the actual user/assistant conversation requested here.
                metadata = {}
                if payload.get('phase'):
                    metadata['phase'] = payload.get('phase')
                turn_id = (payload.get('internal_chat_message_metadata_passthrough') or {}).get('turn_id')
                if turn_id:
                    metadata['turn_id'] = turn_id
                for text in content_texts(payload.get('content')):
                    if role == 'user' and text.lstrip().startswith(SKIP_USER_PREFIXES):
                        continue
                    ev = {'ts': ts, 'role': role, 'text': text}
                    if metadata:
                        ev['metadata'] = metadata
                    events.append(ev)
            elif ptype == 'function_call':
                call_id = payload.get('call_id') or payload.get('id') or f'call_{len(events)}'
                events.append({
                    'ts': ts,
                    'role': 'tool',
                    'tool_name': payload.get('name') or 'unknown',
                    'tool_call_id': call_id,
                    'input': parse_json_arg(payload.get('arguments')),
                    'output': None,
                })
            elif ptype == 'function_call_output':
                call_id = payload.get('call_id') or payload.get('id') or f'call_{len(events)}'
                events.append({
                    'ts': ts,
                    'role': 'tool',
                    'tool_name': '<result>',
                    'tool_call_id': call_id,
                    'input': None,
                    'output': payload.get('output'),
                })
            elif ptype == 'custom_tool_call':
                call_id = payload.get('call_id') or payload.get('id') or f'call_{len(events)}'
                ev = {
                    'ts': ts,
                    'role': 'tool',
                    'tool_name': payload.get('name') or 'custom_tool',
                    'tool_call_id': call_id,
                    'input': payload.get('input'),
                    'output': None,
                }
                if payload.get('status'):
                    ev['metadata'] = {'status': payload.get('status')}
                events.append(ev)
            elif ptype == 'custom_tool_call_output':
                call_id = payload.get('call_id') or payload.get('id') or f'call_{len(events)}'
                events.append({
                    'ts': ts,
                    'role': 'tool',
                    'tool_name': '<result>',
                    'tool_call_id': call_id,
                    'input': None,
                    'output': payload.get('output'),
                })
            elif ptype == 'web_search_call':
                call_id = payload.get('id') or f'web_search_{len(events)}'
                events.append({
                    'ts': ts,
                    'role': 'tool',
                    'tool_name': 'web_search',
                    'tool_call_id': call_id,
                    'input': payload.get('action'),
                    'output': {'status': payload.get('status')},
                })
            elif ptype == 'tool_search_call':
                call_id = payload.get('id') or f'tool_search_{len(events)}'
                events.append({
                    'ts': ts,
                    'role': 'tool',
                    'tool_name': 'tool_search',
                    'tool_call_id': call_id,
                    'input': payload,
                    'output': None,
                })
            elif ptype == 'tool_search_output':
                call_id = payload.get('call_id') or payload.get('id') or f'tool_search_{len(events)}'
                events.append({
                    'ts': ts,
                    'role': 'tool',
                    'tool_name': '<result>',
                    'tool_call_id': call_id,
                    'input': None,
                    'output': payload.get('output') if 'output' in payload else payload,
                })
            elif ptype == 'reasoning':
                summary = payload.get('summary')
                if isinstance(summary, list):
                    summary_text = '\n'.join(str(x) for x in summary if x)
                else:
                    summary_text = str(summary) if summary else ''
                if summary_text:
                    events.append({'ts': ts, 'role': 'assistant', 'thinking': summary_text})

        elif top_type == 'event_msg':
            if ptype == 'token_count':
                info = payload.get('info') or {}
                usage = info.get('total_token_usage') if isinstance(info, dict) else None
                if isinstance(usage, dict) and isinstance(usage.get('total_tokens'), int):
                    last_tokens_total = usage.get('total_tokens')
            elif ptype == 'thread_settings_applied':
                settings = payload.get('thread_settings') or {}
                if settings.get('model'):
                    last_model = settings.get('model')
        elif top_type == 'token_usage_record':
            usage = payload.get('thread_token_usage') or payload.get('usage') or {}
            if isinstance(usage, dict) and isinstance(usage.get('total_tokens'), int):
                last_tokens_total = usage.get('total_tokens')
        elif top_type == 'world_state':
            state = payload.get('state') or {}
            collab = state.get('collaboration_mode') or {}
            if collab.get('model'):
                last_model = collab.get('model')

    if not events:
        return None

    out_events = [add_base(ev, session_id, seq, redacted_total) for seq, ev in enumerate(events)]
    dest_dir = LOG_ROOT / GITHUB_LOGIN / session_date
    dest_dir.mkdir(parents=True, exist_ok=True)
    dest_path = dest_dir / f'{TOOL}__{session_id}.jsonl'
    dest_path.write_text('\n'.join(json.dumps(ev, ensure_ascii=False) for ev in out_events) + '\n', encoding='utf-8')

    first_ts = out_events[0]['ts']
    last_ts = out_events[-1]['ts']
    entry = {
        'session_id': session_id,
        'tool': TOOL,
        'started_at': started_at,
        'last_event_at': last_ts,
        'event_count': len(out_events),
        'raw_event_count': len(raw_objects),
        'file_path': f'logs/{GITHUB_LOGIN}/{session_date}/{TOOL}__{session_id}.jsonl',
        'collection_mode': 'vscode_extension' if meta.get('source') == 'vscode' else 'cli',
        'health': 'degraded' if invalid_lines else 'ok',
        'source_transcript': str(path),
    }
    if last_model:
        entry['model'] = last_model
    if isinstance(last_tokens_total, int):
        entry['tokens_total'] = last_tokens_total
    if redacted_total[0]:
        entry['redacted_count_total'] = redacted_total[0]
    if invalid_lines:
        entry['data_completeness_warning'] = f'skipped {invalid_lines} invalid JSONL line(s) from source transcript'

    return {
        'path': dest_path,
        'entry': entry,
        'events': len(out_events),
        'date': session_date,
        'source': path,
        'redacted': redacted_total[0],
    }


member_dir = LOG_ROOT / GITHUB_LOGIN
member_dir.mkdir(parents=True, exist_ok=True)
manifest_path = member_dir / 'manifest.json'
if manifest_path.exists():
    manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
else:
    manifest = {'schema_version': SCHEMA_VERSION, 'team_id': TEAM_ID, 'github_login': GITHUB_LOGIN, 'generator': GENERATOR, 'sessions': []}

results = []
skipped = []
for path in sorted(SESSIONS_ROOT.glob('2026/*/*/rollout-*.jsonl')):
    session_date = date_from_path(path)
    if session_date < SINCE_DATE:
        continue
    res = convert(path)
    if res is None:
        # capture skipped cwd/date for summary
        try:
            meta = None
            with path.open(encoding='utf-8', errors='replace') as f:
                for line in f:
                    if not line.strip():
                        continue
                    try:
                        obj = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    if obj.get('type') == 'session_meta':
                        meta = obj.get('payload') or {}
                        break
            skipped.append((session_date, path.name, (meta or {}).get('cwd')))
        except Exception:
            skipped.append((session_date, path.name, None))
    else:
        results.append(res)

replace_ids = {r['entry']['session_id'] for r in results}
manifest['sessions'] = [s for s in manifest.get('sessions', []) if s.get('session_id') not in replace_ids]
manifest['sessions'].extend(r['entry'] for r in results)
manifest['sessions'].sort(key=lambda s: (s.get('started_at', ''), s.get('session_id', '')))
manifest['schema_version'] = SCHEMA_VERSION
manifest['team_id'] = TEAM_ID
manifest['github_login'] = GITHUB_LOGIN
manifest['generator'] = GENERATOR
manifest['updated_at'] = iso_now()
manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

print('generated', len(results), 'session log(s)')
for r in results:
    print(f"  {r['date']} {r['entry']['session_id']} events={r['events']} redacted={r['redacted']} -> {r['path'].relative_to(PROJECT_ROOT)}")
print('skipped', len(skipped), 'session(s) since', SINCE_DATE)
for date, name, cwd in skipped:
    reason = 'before/current-project-filter' if cwd else 'no session_meta'
    if cwd and not is_project_cwd(cwd):
        reason = f'cwd outside project: {cwd}'
    print(f'  {date} {name} ({reason})')
print('manifest', manifest_path.relative_to(PROJECT_ROOT), 'sessions=', len(manifest.get('sessions', [])))
